"""
Data Science Question Builder (ds_5 to ds_100)
Provides 96 distinct, high-quality interview questions for Data Science.
"""

def get_ds_questions():
    questions_raw = [
        # Classical Machine Learning & Ensembles
        (5, "How do Decision Trees choose splits, and what is the difference between Gini Impurity and Entropy?", "Easy",
         ["decision tree", "gini impurity", "entropy", "information gain", "split", "CART", "ID3"],
         "Explain the mathematical intuition: Gini measures probability of misclassification; Entropy measures bits of information disorder.",
         "Decision trees partition feature space recursively to maximize node purity. In the CART algorithm, Gini Impurity measures the frequency with which a randomly chosen element from the set would be incorrectly labeled if it were randomly labeled according to the distribution of labels in the subset (ranging from 0 for pure to 0.5 for a 50/50 binary split). In ID3/C4.5, Information Gain is based on Shannon Entropy, measuring the disorder or unexpectedness of information (ranging from 0 to 1). While Gini is computationally faster because it avoids logarithmic calculations, both metrics produce very similar tree architectures in practice."),

        (6, "What is the difference between Bagging and Boosting? Compare Random Forests with Gradient Boosting.", "Medium",
         ["bagging", "boosting", "random forest", "gradient boosting", "variance reduction", "bias reduction", "sequential", "parallel"],
         "Contrast parallel training of independent deep trees (Bagging/Random Forest) with sequential training of shallow trees correcting residual errors (Boosting).",
         "Bagging (Bootstrap Aggregating) trains multiple high-variance, low-bias models (deep decision trees) independently and in parallel on random bootstrap subsets of data with feature subsampling (Random Forest), averaging predictions to reduce overall variance without increasing bias. Boosting trains low-variance, high-bias models (shallow decision trees) sequentially: each successive tree learns to predict the pseudo-residuals (gradients of the loss function) produced by preceding trees, systematically driving down bias. Random Forests are robust against overfitting and easy to tune, whereas Gradient Boosting (e.g. XGBoost) typically achieves higher predictive accuracy but requires careful regularization against overfitting."),

        (7, "How does XGBoost achieve faster training and higher accuracy compared to standard Gradient Boosting?", "Hard",
         ["XGBoost", "second order gradient", "hessian", "regularization", "tree pruning", "histogram", "parallelization", "sparsity"],
         "Highlight second-order Taylor expansion (Gradients and Hessians), L1/L2 leaf weight regularization, and sparsity-aware split finding.",
         "XGBoost improves upon traditional gradient boosting in algorithmic optimization and systems engineering: 1) Second-Order Optimization: It uses a second-order Taylor expansion of the loss function, incorporating both first-order gradients and second-order Hessians for more precise Newton-Raphson tree steps; 2) Regularization: It includes explicit L1 (alpha) and L2 (lambda) penalties on leaf weights directly inside the objective function to penalize tree complexity and prevent overfitting; 3) Sparsity-Aware Split Finding: It automatically learns default split directions for missing values; 4) Computational efficiency: It pre-sorts column blocks in compressed memory, enabling parallelized split evaluation and out-of-core disk computation."),

        (8, "Explain how Support Vector Machines (SVMs) find the optimal hyperplane and how the Kernel Trick works.", "Medium",
         ["SVM", "hyperplane", "margin", "support vectors", "kernel trick", "RBF", "dual problem", "convex optimization"],
         "Explain maximizing the geometric margin between classes, support vectors defining the decision boundary, and mapping data into higher dimensions.",
         "A Support Vector Machine (SVM) finds the optimal separating hyperplane that maximizes the geometric margin (the distance between the decision boundary and the closest data points of any class, known as Support Vectors). For linearly non-separable data, the Kernel Trick implicitly projects input features into a higher- or infinite-dimensional Hilbert space where the data becomes linearly separable, without ever explicitly computing the coordinates in that high-dimensional space. By replacing the dot product in the dual optimization problem with a Kernel Function (such as Radial Basis Function / RBF or Polynomial), SVMs compute high-dimensional similarity efficiently in O(d) time."),

        (9, "What is the difference between L1 (Lasso) and L2 (Ridge) regularization, and why does L1 produce sparse weights?", "Medium",
         ["L1 regularization", "L2 regularization", "lasso", "ridge", "sparsity", "feature selection", "contour", "gradient"],
         "Draw the geometric contours: L1 has diamond corners on axes causing coefficients to hit zero; L2 has circular contours shrinking weights toward zero.",
         "L1 (Lasso) adds the sum of absolute parameter weights (|w|) to the loss function, while L2 (Ridge) adds the sum of squared parameter weights (w^2). Geometrically, the constraint region for L1 is a diamond/polytope with sharp vertices aligned along the coordinate axes, while L2 is a hypersphere/circle. When the elliptical contours of the objective loss function intersect the constraint region, L1 is far more likely to intersect at a vertex where one or more feature weights become exactly zero, effectively performing embedded feature selection. L2 shrinks all weights proportionally toward zero but rarely sets them to zero, making it superior for multicollinear features."),

        (10, "How does Principal Component Analysis (PCA) work, and how do you choose the number of components?", "Medium",
         ["PCA", "dimensionality reduction", "covariance matrix", "eigenvalues", "eigenvectors", "explained variance", "orthogonal", "scree plot"],
         "Explain centering data, computing the covariance matrix, extracting orthogonal eigenvectors sorted by eigenvalues, and using cumulative variance plots.",
         "Principal Component Analysis (PCA) is an unsupervised linear dimensionality reduction technique that projects high-dimensional data onto orthogonal axes (Principal Components) that maximize explained variance. The algorithm: 1) Mean-centers and standardizes features; 2) Calculates the covariance matrix of the features; 3) Computes the eigenvalues and eigenvectors of the covariance matrix; 4) Sorts eigenvectors in descending order of their corresponding eigenvalues. To choose the number of components, practitioners evaluate a Scree Plot or calculate the Cumulative Explained Variance ratio, typically retaining enough components to capture 85%-95% of total dataset variance."),

        (11, "Explain K-Means clustering, the Elbow Method, and the Silhouette Score for determining optimal k.", "Easy",
         ["K-Means", "clustering", "elbow method", "silhouette score", "inertia", "centroid", "unsupervised", "Euclidean"],
         "Explain centroid assignment and update steps, limitations (spherical clusters), and contrast WCSS (inertia) with intra-cluster vs nearest-cluster distances.",
         "K-Means partitions data into k non-overlapping clusters by iteratively assigning each data point to its nearest centroid (using Euclidean distance) and updating centroids to the mean of their assigned points until convergence. Because k must be specified upfront, practitioners evaluate two metrics: 1) The Elbow Method plots Within-Cluster Sum of Squares (WCSS / Inertia) against k, identifying the 'elbow' where marginal gains in variance drop off; 2) The Silhouette Score evaluates each point's cohesion (average distance to points in its own cluster, a) against separation (average distance to points in the nearest neighboring cluster, b), scored as (b - a) / max(a, b) from -1 to +1. Higher average silhouette indicates well-separated, compact clusters."),

        (12, "When would you choose DBSCAN over K-Means for clustering?", "Medium",
         ["DBSCAN", "K-Means", "density based", "noise", "outliers", "arbitrary shapes", "epsilon", "minPts"],
         "Contrast K-Means assumption of spherical, equal-variance clusters with DBSCAN's density-reachability and automatic outlier detection.",
         "K-Means assumes clusters are spherical, convex, and roughly equal in size, and it forces every data point into a cluster regardless of noise. DBSCAN (Density-Based Spatial Clustering of Applications with Noise) groups points based on local point density defined by two hyperparameters: Epsilon (neighborhood radius) and MinPts (minimum points required to form a dense region). Points with >= MinPts neighbors are Core Points; points within epsilon of a core point are Border Points; and isolated points are classified as Noise / Outliers. DBSCAN is chosen when clusters have arbitrary, non-linear geometric shapes (e.g. concentric circles), when the number of clusters is unknown, or when robust outlier rejection is critical."),

        (13, "How does the ROC-AUC metric work, and why is PR-AUC preferred for highly skewed datasets?", "Hard",
         ["ROC-AUC", "PR-AUC", "true positive rate", "false positive rate", "precision", "recall", "imbalanced data", "confusion matrix"],
         "Explain that ROC graphs TPR vs FPR (where large True Negatives dilute FPR), whereas PR graphs Precision vs Recall (ignoring True Negatives).",
         "The ROC curve plots True Positive Rate (Sensitivity / Recall) against False Positive Rate (FPR = FP / (FP + TN)) across all classification probability thresholds; the Area Under the Curve (ROC-AUC) represents the probability that a random positive sample is ranked higher than a random negative sample. However, in heavily imbalanced problems (e.g., fraud detection with 99.9% negative transactions), the massive count of True Negatives (TN) in the denominator keeps FPR artificially near zero, giving an overly optimistic picture of model performance. Precision-Recall AUC (PR-AUC) evaluates Precision (TP / (TP + FP)) against Recall (TP / (TP + FN)), focusing solely on the minority positive class without distortion from abundant true negatives."),

        (14, "What is Multicollinearity, and how do you detect and resolve it in regression models?", "Medium",
         ["multicollinearity", "VIF", "correlation", "regression", "standard error", "coefficients", "feature selection", "condition number"],
         "Define multicollinearity as high correlation among predictors, explain Variance Inflation Factor (VIF > 5-10), and resolve via removal, PCA, or Ridge.",
         "Multicollinearity occurs in linear models when two or more independent predictor variables are highly correlated, meaning one can be linearly predicted from the others. While it does not reduce the overall predictive power or R-squared of the model, it inflates the standard errors of regression coefficients, making coefficients unstable, erratic, and impossible to interpret causally. It is detected using correlation matrices and Variance Inflation Factor (VIF), where VIF > 5 to 10 indicates severe redundancy. Mitigations include dropping redundant features, combining collinear variables, applying dimensionality reduction (PCA), or adopting L2 Ridge Regularization."),

        # Deep Learning & Neural Networks
        (15, "Walk me through the Backpropagation algorithm and how the Chain Rule calculates gradients.", "Hard",
         ["backpropagation", "chain rule", "gradient descent", "computational graph", "forward pass", "backward pass", "activation function"],
         "Structure into Forward Pass (computes loss), Computational Graph representation, and Backward Pass applying the multivariable calculus chain rule.",
         "Backpropagation calculates the gradient of the loss function with respect to every trainable weight and bias in a neural network to enable gradient descent updates. 1) Forward Pass: Input vectors propagate forward through affine transformations (z = Wx + b) and non-linear activation functions (a = sigma(z)) across successive layers to produce predictions, evaluating the loss L against target labels. 2) Backward Pass: The algorithm traverses the computational graph in reverse. Using the multivariable Chain Rule of calculus, the error gradient at layer l is computed by multiplying the incoming gradient from layer l+1 by the Jacobian of the local layer operations (dL/dW = dL/da * da/dz * dz/dW). Gradients are accumulated and used to update weights."),

        (16, "Explain the Vanishing and Exploding Gradient problems and how modern architectures solve them.", "Hard",
         ["vanishing gradient", "exploding gradient", "ReLU", "ResNet", "skip connection", "batch norm", "gradient clipping", "LSTM"],
         "Explain how deep chain rule multiplications of small (<1) derivatives vanish gradients and large (>1) weights cause exploding gradients.",
         "During backpropagation in deep networks, gradients are computed via repeated matrix multiplications across layers. When saturating activations (like Sigmoid or Tanh, whose derivatives are <= 0.25) or small initial weights are used, the backpropagated gradients shrink exponentially with depth, causing early layers to train imperceptibly slowly (Vanishing Gradients). Conversely, large initial weights can cause gradients to grow exponentially, resulting in numerical overflow and unstable oscillations (Exploding Gradients). Solutions include: 1) Non-saturating activations like ReLU and GELU; 2) Residual Skip Connections (ResNet) providing an uninterrupted identity gradient highway; 3) Normalization layers (BatchNorm, LayerNorm); 4) Xavier and He weight initialization; and 5) Gradient Clipping for exploding gradients in RNNs."),

        (17, "What is the difference between Batch Normalization and Layer Normalization?", "Medium",
         ["batch normalization", "layer normalization", "covariate shift", "mini-batch", "RNN", "Transformer", "vision", "statistics"],
         "Contrast Batch Normalization (normalizing across the batch dimension for each channel/feature) with Layer Normalization (normalizing across features for each single sample).",
         "Batch Normalization normalizes activations across the mini-batch dimension for each individual feature or channel independently, maintaining running mean and variance statistics for inference. It accelerates CNN training and acts as a regularizer, but depends on mini-batch size (failing when batch size is small or 1) and does not adapt well to variable-length sequences. Layer Normalization computes mean and variance across all hidden feature dimensions for each individual data sample independently. Because it has zero dependency on other samples in the batch, LayerNorm is invariant to batch size and is the universal standard for recurrent architectures and modern Transformer models (BERT, GPT, LLaMA)."),

        (18, "How do Convolutional Neural Networks (CNNs) achieve parameter sharing and translation equivariance?", "Medium",
         ["CNN", "convolution", "kernel", "filter", "parameter sharing", "receptive field", "translation equivariance", "pooling"],
         "Explain spatial locality: small filters sliding across feature maps sharing the same weight matrix, drastically reducing parameter count.",
         "Unlike fully connected layers where every input pixel connects to every neuron via a distinct weight, CNNs enforce spatial locality through Parameter Sharing: a small learnable filter/kernel (e.g., 3x3) slides across the input tensor computing localized dot products. The same filter weights are reused across the entire spatial grid, drastically reducing parameter count and memory footprint. This sliding operation confers Translation Equivariance: if a feature (such as an edge or eye) shifts spatially in the input image, its representation in the output feature map shifts by the exact same amount. Max pooling and strided convolutions then downsample spatial dimensions, expanding the receptive field of deeper layers."),

        (19, "Explain the Transformer architecture: Scaled Dot-Product Attention and Multi-Head Attention.", "Hard",
         ["Transformer", "attention", "query key value", "softmax", "multi-head attention", "scaled dot-product", "Vaswani"],
         "Write the formula Attention(Q, K, V) = softmax(QK^T / sqrt(d_k)) * V. Explain why scaling by sqrt(d_k) prevents vanishing softmax gradients.",
         "The Transformer replaces recurrent recurrence with Self-Attention. Input vectors are projected through learnable linear matrices into Queries (Q), Keys (K), and Values (V). In Scaled Dot-Product Attention, the dot product of Q and K measures pairwise token relevance; this is scaled by 1/sqrt(d_k) to prevent dot products from growing excessively large in high dimensions (which would push softmax into regions with vanishing gradients). Softmax converts these logits into attention weights, which compute a weighted sum over Values: Attention(Q,K,V) = softmax(Q K^T / sqrt(d_k)) * V. Multi-Head Attention runs this mechanism h times in parallel with distinct projections, allowing the model to jointly attend to information from different representation subspaces (e.g., syntactic vs semantic relationships) at different positions."),

        (20, "What is the difference between Autoencoding (BERT) and Autoregressive (GPT) language models?", "Medium",
         ["BERT", "GPT", "autoencoding", "autoregressive", "masked language model", "causal attention", "bidirectional", "generative"],
         "Contrast BERT's bidirectional context for classification/extraction with GPT's unidirectional causal masking for text generation.",
         "BERT (Bidirectional Encoder Representations from Transformers) is an Autoencoding model based on the Transformer Encoder. It is trained via Masked Language Modeling (MLM), predicting randomly masked tokens by attending bi-directionally to both left and right context simultaneously. It excels at language understanding tasks (text classification, named entity recognition, extractive question answering), but cannot generate fluent continuous text. GPT (Generative Pre-trained Transformer) is an Autoregressive model based on the Transformer Decoder. It is trained to predict the next token given preceding tokens, using Causal Masking to prevent positions from attending to future tokens. It excels at text generation, conversational AI, and few-shot reasoning."),

        # Statistics, Probability & A/B Testing
        (21, "Explain the Central Limit Theorem (CLT) and why it is fundamental to inferential statistics.", "Easy",
         ["central limit theorem", "normal distribution", "sampling distribution", "sample mean", "variance", "hypothesis testing", "CLT"],
         "State clearly: regardless of the underlying population distribution, the distribution of sample means approaches a normal distribution as sample size n increases.",
         "The Central Limit Theorem (CLT) states that the sampling distribution of the sample mean approaches a Normal (Gaussian) distribution as the sample size n becomes large (typically n >= 30), regardless of the shape or skewness of the underlying population distribution (provided the population has a finite mean and variance). This theorem is foundational to data science because it allows practitioners to perform parametric hypothesis testing (Z-tests, t-tests) and construct confidence intervals for real-world metrics (like revenue, latency, or conversion rates) whose raw distributions are highly non-normal or skewed."),

        (22, "What is a p-value, and what are common misconceptions about its interpretation?", "Easy",
         ["p-value", "null hypothesis", "significance level", "type I error", "statistical significance", "misconceptions"],
         "Define it precisely: the probability of observing data as extreme or more extreme, assuming the null hypothesis is true. It is NOT the probability that H0 is true.",
         "A p-value is the probability of obtaining test results at least as extreme as the actual observed data, assuming that the Null Hypothesis (H0) is true. It quantifies the compatibility of the evidence with the null model. Common misconceptions include: 1) Believing the p-value is the probability that the null hypothesis is true (p(Data|H0) != p(H0|Data)); 2) Believing 1 - p is the probability that the alternative hypothesis is true; 3) Confusing statistical significance (low p-value due to massive sample size) with practical or commercial significance (effect size); and 4) Assuming p > 0.05 proves the null hypothesis is true (absence of evidence is not evidence of absence)."),

        (23, "Explain Type I vs Type II errors and how they relate to Statistical Power in A/B testing.", "Medium",
         ["type I error", "type II error", "statistical power", "alpha", "beta", "false positive", "false negative", "sample size"],
         "Define Alpha (False Positive, rejecting true H0) and Beta (False Negative, failing to reject false H0). Power = 1 - Beta.",
         "In hypothesis testing: 1) Type I Error (Alpha, False Positive) occurs when we reject a true null hypothesis (e.g., declaring a feature launch improved conversion when it did not). Standard alpha threshold is typically 5%. 2) Type II Error (Beta, False Negative) occurs when we fail to reject a false null hypothesis (e.g., abandoning an experiment that genuinely improved conversion). Statistical Power is defined as 1 - Beta (typically targeted at 80% or 90%), representing the probability of correctly detecting a true effect of a specified Minimum Detectable Effect (MDE). Power increases with larger sample sizes, higher effect sizes, and lower metric variance."),

        (24, "How do you calculate the required Sample Size for an A/B test before launching?", "Hard",
         ["sample size", "A/B testing", "MDE", "minimum detectable effect", "power", "variance", "alpha", "power calculation"],
         "Discuss parameters: baseline conversion rate, Minimum Detectable Effect (MDE), significance level (alpha), and statistical power (1 - beta).",
         "Pre-experiment power calculation determines the minimum sample size required to detect a meaningful business effect without wasting traffic or underpowering the test. The formula depends on: 1) Significance level (alpha, typically 0.05 for 95% confidence); 2) Statistical power (1 - beta, typically 0.80); 3) Baseline metric variance (sigma^2, for proportions p*(1-p)); and 4) Minimum Detectable Effect (MDE, the smallest relative or absolute lift worth detecting). For binary conversion rates, sample size per variant is roughly N = 16 * (p*(1-p)) / (MDE^2). Halving the MDE requires a 4x increase in sample size due to the inverse square relationship."),

        (25, "What is Simpson's Paradox, and how can it lead to wrong business decisions?", "Medium",
         ["simpson's paradox", "confounding variable", "aggregation", "stratification", "causality", "A/B testing"],
         "Explain when a trend or superiority appears in several aggregated groups but reverses when the groups are combined, caused by a confounding variable.",
         "Simpson's Paradox is a statistical phenomenon where a trend or correlation appears in several distinct subgroups of data, but completely disappears or reverses when the subgroups are combined into an aggregate total. This is caused by an unobserved Confounding Variable that has unequal distributions across the groups. For example, in an e-commerce A/B test, Variant B might show higher conversion rates on mobile devices and higher conversion rates on desktop devices, yet Variant A shows higher overall conversion because Variant A happened to receive a much higher proportion of desktop traffic (which naturally converts at a higher baseline). Resolving it requires stratified analysis and controlled randomized split-testing."),
    ]

    # Additional 71 questions to reach 96 new questions (ds_5 to ds_100)
    topics_26_to_100 = [
        (26, "How does Bayes' Theorem update prior beliefs with observed evidence?", "Easy",
         ["bayes theorem", "prior", "posterior", "likelihood", "evidence", "conditional probability"],
         "Formula: P(A|B) = [P(B|A) * P(A)] / P(B). Walk through a medical diagnostic test example with false positives.",
         "Bayes' Theorem provides a mathematical framework for updating the probability of a hypothesis (Posterior) based on observed data (Likelihood) and prior background knowledge (Prior): P(A|B) = P(B|A) * P(A) / P(B). In clinical testing, if a rare disease affects 0.1% of the population (Prior P(D) = 0.001) and a test has 99% accuracy (Sensitivity P(+|D) = 0.99, False Positive Rate P(+|~D) = 0.01), a positive result does not mean a 99% chance of disease. Because healthy individuals vastly outnumber sick ones, false positives outnumber true positives, resulting in a posterior probability of approximately ~9%."),

        (27, "What is Maximum Likelihood Estimation (MLE) and how does it relate to Ordinary Least Squares (OLS)?", "Hard",
         ["MLE", "maximum likelihood", "OLS", "loss function", "log likelihood", "normal distribution", "optimization"],
         "Explain maximizing the likelihood function of observed data under assumed parameter distributions, and show OLS is MLE under Gaussian noise.",
         "Maximum Likelihood Estimation (MLE) is a probabilistic method for estimating the parameters of a statistical model by finding the parameter values that maximize the Likelihood Function (the probability of observing the given sample data under the assumed distribution). In practice, we maximize the Log-Likelihood to convert products of probabilities into tractable sums. Ordinary Least Squares (OLS) regression minimizes the sum of squared residuals; mathematically, minimizing squared error is identical to maximizing the Gaussian log-likelihood under the assumption that residuals are normally distributed with constant variance."),

        (28, "How do you detect and handle Data Leakage in machine learning pipelines?", "Medium",
         ["data leakage", "target leakage", "train test split", "preprocessing", "cross-validation", "pipeline", "temporal leakage"],
         "Differentiate target leakage (features containing future info) from train-test contamination (scaling/imputing before splitting).",
         "Data leakage occurs when information from outside the training dataset is inadvertently used to train a model, producing deceptively high validation scores but catastrophic failure in production. 1) Train-Test Contamination: Performing preprocessing (mean imputation, standard scaling, PCA, or feature selection) on the entire dataset before splitting. Fix: Fit transformers strictly on training folds within Scikit-Learn Pipelines. 2) Target Leakage: Including features that are proxies for the target or only become available after the prediction event (e.g., using 'refund_date' to predict customer churn). 3) Temporal Leakage: Splitting time-series data randomly instead of chronologically."),

        (29, "Explain Time-Series Stationarity and how the Augmented Dickey-Fuller (ADF) test evaluates it.", "Medium",
         ["stationarity", "ADF test", "time series", "differencing", "mean", "variance", "autocorrelation", "unit root"],
         "Define weak stationarity: constant mean, constant variance, and autocovariance depending only on time lag. Explain differencing to remove trends.",
         "A time series is weakly stationary if its statistical properties—specifically its mean, variance, and autocovariance—remain constant over time. Most time series models (like ARIMA) require stationarity because statistical estimation assumes underlying generating processes do not drift. The Augmented Dickey-Fuller (ADF) test evaluates stationarity: the Null Hypothesis (H0) states the series has a unit root (is non-stationary). If the p-value is < 0.05, we reject the null hypothesis and conclude the series is stationary. Non-stationary series with trends or seasonality are transformed into stationary series via differencing (y_t - y_{t-1}) or log transformations."),

        (30, "What is the difference between Generative AI (LLMs) and Discriminative Machine Learning models?", "Easy",
         ["generative", "discriminative", "joint probability", "conditional probability", "LLM", "classification"],
         "Contrast discriminative models learning decision boundaries P(Y|X) with generative models learning the joint distribution P(X, Y) or P(X).",
         "Discriminative models learn the conditional probability distribution P(Y|X)—the boundary between classes given input features. They focus on classifying or predicting labels from inputs (e.g., Logistic Regression, SVMs, Random Forests, image classifiers). Generative models learn the joint probability distribution P(X, Y) or the underlying distribution of the data P(X). They model how data is generated and can synthesize novel, realistic data samples (e.g., Naive Bayes, GANs, Diffusion Models, and Autoregressive Large Language Models like GPT generating text by predicting token probability distributions)."),

        (31, "Explain Retrieval-Augmented Generation (RAG) architecture and how it grounds LLM responses.", "Medium",
         ["RAG", "vector database", "embeddings", "cosine similarity", "hallucination", "retrieval", "chunking", "semantic search"],
         "Walk through: Document Chunking -> Embeddings -> Vector DB indexing -> User query retrieval -> Augmenting prompt context -> LLM synthesis.",
         "Retrieval-Augmented Generation (RAG) mitigates LLM hallucinations and knowledge cutoff limitations by grounding generation in external verified documents. The pipeline: 1) Ingestion: Domain documents are chunked into semantic passages (e.g. 500 tokens with 50-token overlap) and converted into dense vector embeddings using models like text-embedding-3; 2) Storage: Vectors are indexed in a Vector Database (Pinecone, Chroma, Milvus) using HNSW graphs; 3) Retrieval: When a user asks a question, their query is embedded, and cosine similarity retrieves the top-k most relevant text chunks; 4) Synthesis: The retrieved chunks are injected into the LLM system prompt as factual context, prompting the model to generate accurate, sourced answers."),

        (32, "How do Low-Rank Adaptation (LoRA) and QLoRA enable parameter-efficient fine-tuning (PEFT)?", "Hard",
         ["LoRA", "QLoRA", "PEFT", "fine-tuning", "low-rank", "adapter", "quantization", "GPU memory"],
         "Explain freezing base weights W_0 and decomposing weight updates into two low-rank matrices Delta W = B * A where rank r << d.",
         "Full fine-tuning of billions of LLM parameters requires massive GPU VRAM to store optimizer states and gradients for every weight. LoRA freezes the original pre-trained weight matrix W_0 (size d x k) and injects trainable low-rank decomposition matrices Delta W = B * A, where B is d x r and A is r x k, with rank r << min(d, k) (e.g., r = 8 or 16). Because r is tiny, LoRA reduces trainable parameters by over 99% while achieving comparable task performance. QLoRA further optimizes memory by quantizing the base model weights to 4-bit NormalFloat (NF4) with Double Quantization and Paged Optimizers, enabling fine-tuning of 70B models on a single consumer GPU."),

        (33, "What is Vector Embeddings Cosine Similarity and how does it differ from Euclidean Distance?", "Easy",
         ["cosine similarity", "euclidean distance", "dot product", "vector embedding", "angle", "magnitude", "normalization"],
         "Cosine similarity measures the angle between vectors (invariant to magnitude); Euclidean distance measures geometric straight-line length.",
         "Cosine Similarity measures the cosine of the angle between two non-zero vectors in multi-dimensional space: Cosine = (A . B) / (||A|| * ||B||). It ranges from -1 to +1, evaluating directional alignment regardless of vector magnitude. This makes it ideal for text embeddings, where document length or token frequency variations inflate vector magnitude without altering semantic meaning. Euclidean Distance measures the geometric straight-line distance between two points: sqrt(sum((A_i - B_i)^2)). If vectors are L2-normalized to unit length (||A|| = 1), Euclidean distance and Cosine similarity are mathematically monotonic inverses."),

        (34, "How do you detect Concept Drift vs Data Drift in production ML systems?", "Medium",
         ["concept drift", "data drift", "covariate shift", "Kolmogorov-Smirnov", "PSI", "model monitoring", "retraining"],
         "Data Drift (Covariate Shift): P(X) changes while P(Y|X) remains constant. Concept Drift: P(Y|X) changes (the relationship between features and target shifts).",
         "In production machine learning: 1) Data Drift (Covariate Shift) occurs when the distribution of input features P(X) changes over time while the underlying relationship between inputs and outputs P(Y|X) remains unchanged (e.g., macroeconomic inflation shifts user salary distributions). It is detected by statistical tests comparing production distributions to training baselines (Kolmogorov-Smirnov test for continuous variables, Population Stability Index / PSI). 2) Concept Drift occurs when the statistical relationship between features and the target P(Y|X) changes (e.g., consumer purchasing habits abruptly changing during a pandemic). It is detected by tracking rolling model performance metrics (F1, MSE) against true production labels."),

        (35, "Explain the Cold Start problem in Recommender Systems and how to mitigate it.", "Medium",
         ["cold start", "recommender systems", "collaborative filtering", "content-based", "matrix factorization", "hybrid"],
         "Differentiate User Cold Start (new user with no interaction history) from Item Cold Start (new product with no ratings).",
         "The Cold Start problem occurs in collaborative filtering systems when new users or new items lack sufficient interaction history (ratings, clicks, purchases) to generate personalized recommendations. Mitigations include: 1) For New Users: Onboarding interest questionnaires, contextual recommendations (recommending trending/popular items filtered by geo-location, device, or referral source), and multi-armed bandit exploration algorithms (Thompson Sampling); 2) For New Items: Content-Based Filtering using metadata embeddings (product category, textual descriptions, tags) to compute semantic similarity to existing catalog items; 3) Hybrid Recommender Architectures combining collaborative filtering with deep content representations."),

        (36, "What is Collaborative Filtering vs Content-Based Filtering in Recommenders?", "Easy",
         ["collaborative filtering", "content-based", "user-user", "item-item", "matrix factorization", "SVD", "cold start"],
         "Collaborative filtering learns from user-item interaction matrices (wisdom of crowds); Content-based learns from item attributes/metadata.",
         "Content-Based Filtering recommends items by analyzing the explicit attributes and metadata of items a user previously enjoyed (e.g., recommending a movie because it shares the same genre, director, and actors as movies the user rated 5 stars). It requires zero user-community data and avoids cold starts for items, but fails to provide serendipitous discoveries. Collaborative Filtering recommends items based on the collective behavior and preferences of other similar users ('users who liked X also liked Y'). It operates via User-User / Item-Item similarity or Matrix Factorization (SVD / ALS), discovering latent non-obvious patterns, but suffers from cold-start bottlenecks."),

        (37, "How does Matrix Factorization (e.g., SVD or ALS) uncover latent features in recommendation matrices?", "Hard",
         ["matrix factorization", "SVD", "ALS", "latent factors", "collaborative filtering", "sparse matrix", "recommender"],
         "Explain decomposing a sparse user-item rating matrix R (size m x n) into user matrix U (m x k) and item matrix V^T (k x n) via latent dimension k.",
         "In large recommendation platforms, the User-Item interaction matrix R (size m users by n items) is over 99% sparse. Matrix Factorization approximates R as the inner product of two low-rank dense matrices: a User latent matrix P (size m x k) and an Item latent matrix Q (size n x k), where k is the number of latent hidden factors (e.g., preferred movie themes like drama, pacing, humor). Predicted rating is r_ui = P_u . Q_i^T. Alternating Least Squares (ALS) optimizes this objective by alternately holding P fixed while solving a quadratic least-squares problem for Q, and vice-versa, making it highly parallelizable and naturally suited for implicit feedback datasets."),

        (38, "Explain K-Fold Cross Validation and why Stratified K-Fold is mandatory for classification.", "Easy",
         ["k-fold", "stratified k-fold", "cross validation", "generalization", "data split", "class distribution"],
         "Explain partitioning data into K folds, training on K-1 and testing on the remaining fold, rotating K times. Stratified preserves target class proportions.",
         "Cross-validation provides an unbiased estimate of model generalization performance on unseen data. In K-Fold Cross-Validation, the dataset is randomly divided into K equal subsets (folds). The model is trained on K-1 folds and evaluated on the remaining held-out fold; this process repeats K times so each fold serves as the test set exactly once, and metrics are averaged. In standard K-Fold, random sampling can result in some folds having drastically fewer minority class samples. Stratified K-Fold enforces that each fold contains the exact same percentage of target class labels as the complete dataset, which is critical for imbalanced classification."),

        (39, "What is the difference between Precision, Recall, F1-Score, and Specificity?", "Easy",
         ["precision", "recall", "F1-score", "specificity", "confusion matrix", "harmonic mean", "trade-off"],
         "Define each from the confusion matrix: Precision = TP/(TP+FP); Recall = TP/(TP+FN); Specificity = TN/(TN+FP); F1 = harmonic mean of P and R.",
         "These metrics evaluate classification performance beyond accuracy: 1) Precision (Positive Predictive Value) = TP / (TP + FP): Of all samples predicted positive, what proportion was actually positive? Crucial when false positives are expensive (spam filters); 2) Recall (Sensitivity) = TP / (TP + FN): Of all actual positive samples, what proportion did the model correctly identify? Crucial when false negatives are dangerous (cancer screening); 3) Specificity = TN / (TN + FP): True negative rate; 4) F1-Score is the Harmonic Mean of Precision and Recall: 2 * (P * R) / (P + R), balancing both metrics especially under class imbalance."),

        (40, "How do you handle Outliers in training data, and when is it dangerous to simply drop them?", "Medium",
         ["outliers", "isolation forest", "IQR", "z-score", "winsorization", "robust regression", "domain knowledge"],
         "Explain detection (IQR rule, Z-score > 3, Isolation Forests) and treatment (Winsorization/capping, log transforms, robust models like Huber loss).",
         "Outliers are observations that deviate markedly from overall data distribution. They can stem from measurement errors, system anomalies, or genuine rare events. Detection methods include: 1) Interquartile Range (IQR): points beyond Q1 - 1.5*IQR or Q3 + 1.5*IQR; 2) Z-score (> 3 standard deviations); 3) Unsupervised models like Isolation Forests. Simply deleting outliers is dangerous because rare high-value transactions or fraud events may represent the exact signal the model must learn. Responsible treatments include: Winsorization (capping extreme values at the 99th percentile), log or Box-Cox transformations to compress long tails, or using robust algorithms (tree models or Huber loss)."),

        (41, "What is the difference between Parametric and Non-Parametric machine learning models?", "Easy",
         ["parametric", "non-parametric", "assumptions", "linear regression", "KNN", "decision trees", "flexibility"],
         "Parametric models assume a fixed functional form with fixed parameter counts (Linear/Logistic Regression); Non-parametric models grow parameters with data (KNN, Trees).",
         "Parametric machine learning algorithms assume a fixed, predefined functional form for the target mapping function f(X). They summarize data through a fixed number of parameters independent of training set size (e.g., Linear Regression, Logistic Regression, Linear Discriminant Analysis). They are computationally fast, interpretable, and require less data, but suffer from high bias if functional assumptions are wrong. Non-Parametric algorithms make no strong prior assumptions about the functional form: the number of parameters is free to grow dynamically with the size of the training dataset (e.g., K-Nearest Neighbors, Decision Trees, SVMs). They provide extreme flexibility to fit complex patterns but risk overfitting."),

        (42, "Explain the curse of dimensionality and how it degrades distance-based algorithms.", "Medium",
         ["curse of dimensionality", "distance metric", "KNN", "sparsity", "high dimensional", "Euclidean distance", "PCA"],
         "Explain exponential volume growth: in high dimensions, data becomes sparse, all pairwise Euclidean distances become equidistant, and density collapses.",
         "The Curse of Dimensionality refers to the mathematical phenomena that arise when analyzing data in high-dimensional feature spaces. As dimensionality d increases, the volume of the space grows exponentially, causing available data points to become extremely sparse. In distance-based algorithms (like K-Nearest Neighbors, K-Means, and SVMs with Euclidean distance), the ratio of the distance to the nearest neighbor versus the distance to the farthest neighbor converges to 1: every point becomes roughly equidistant from every other point. Distance metrics lose their discriminative power, feature spaces require exponentially more training data to maintain density, and models overfit unless dimensionality reduction is applied."),

        (43, "How does the t-SNE algorithm visualize high-dimensional data, and why can it not be used for feature extraction?", "Hard",
         ["t-SNE", "dimensionality reduction", "perplexity", "Kullback-Leibler", "Student-t", "crowding problem", "visualization"],
         "Explain converting Euclidean distances into probabilities using Gaussian distributions in high-D and Student-t in low-D, minimizing KL divergence.",
         "t-SNE (t-Distributed Stochastic Neighbor Embedding) is an unsupervised non-linear technique designed strictly for high-dimensional visualization. It converts pairwise Euclidean distances between high-dimensional points into conditional probabilities representing similarities using Gaussian distributions. In the low-dimensional embedding (typically 2D), it models similarities using a heavy-tailed Student-t distribution (solving the 'crowding problem' where points clump together), and minimizes the Kullback-Leibler (KL) divergence between the distributions using gradient descent. t-SNE preserves local neighborhood structure exceptionally well, but does not preserve global distances or densities, is computationally non-deterministic, and cannot transform new out-of-sample data points."),

        (44, "What is UMAP (Uniform Manifold Approximation and Projection) and how does it compare to t-SNE?", "Hard",
         ["UMAP", "t-SNE", "manifold learning", "Riemannian geometry", "fuzzy simplicial sets", "visualization", "scalability"],
         "Compare preservation of global structure, computational speed (UMAP is much faster), and ability to transform new unseen data points.",
         "UMAP is a non-linear dimensionality reduction technique grounded in Riemannian geometry and algebraic topology. It assumes data lies on a local manifold and constructs a fuzzy simplicial set representation in high dimensions, then optimizes a low-dimensional layout using cross-entropy. Compared to t-SNE: 1) UMAP preserves both local neighborhood clusters and global data topology (inter-cluster distances remain meaningful); 2) UMAP is significantly faster computationally and scales efficiently to millions of points; and 3) UMAP learns an explicit mapping function, allowing it to transform new, unseen out-of-sample test data, making it viable for both exploratory visualization and preprocessing pipelines."),

        (45, "How does the Adam Optimizer combine the benefits of AdaGrad and RMSprop?", "Medium",
         ["Adam", "optimizer", "momentum", "RMSprop", "AdaGrad", "learning rate", "exponential moving average", "bias correction"],
         "Explain first moment (momentum: moving average of gradients) and second moment (RMSprop: moving average of squared gradients) with bias correction.",
         "Adam (Adaptive Moment Estimation) is an adaptive learning rate optimization algorithm that computes individual adaptive learning rates for each parameter. It combines two concepts: 1) Momentum (from AdaGrad): It calculates the First Moment m_t, an exponential moving average of past gradients, which dampens oscillations and accelerates in consistent directions; 2) Scaling (from RMSprop): It calculates the Second Moment v_t, an exponential moving average of past squared gradients, which scales parameter updates inversely to gradient magnitude. Crucially, Adam introduces Bias Correction terms to counteract the initial zero-bias of m_t and v_t during early training iterations."),

        (46, "What is Transfer Learning and how do you decide between Feature Extraction and Fine-Tuning?", "Easy",
         ["transfer learning", "fine-tuning", "feature extraction", "pre-trained", "frozen layers", "domain similarity", "dataset size"],
         "Evaluate using a 2x2 matrix: Dataset Size (Small vs Large) and Domain Similarity (High vs Low) relative to the pre-trained model.",
         "Transfer Learning leverages knowledge gained from a pre-trained model on a massive source task (e.g., ImageNet or web-scale text) and applies it to a target task. Strategy selection depends on dataset size and domain similarity: 1) Small Dataset, High Similarity: Freeze all base backbone layers (using them as a fixed Feature Extractor) and train only the newly attached classification head to prevent overfitting; 2) Small Dataset, Low Similarity: Problematic; train shallow linear probes on early pre-trained layers; 3) Large Dataset, High Similarity: Fine-tune the entire network with a small learning rate; 4) Large Dataset, Low Similarity: Fine-tune the entire network from pre-trained weights for faster convergence than training from scratch."),

        (47, "Explain the Self-Attention mechanism's time and memory complexity and how FlashAttention optimizes it.", "Hard",
         ["self-attention", "complexity", "O(N^2)", "FlashAttention", "IO-aware", "SRAM", "HBM", "tiling", "GPU memory"],
         "Standard attention computes N x N attention matrix requiring O(N^2) time and memory. FlashAttention uses tiling and kernel fusion to avoid HBM round-trips.",
         "Standard self-attention computes an N x N attention matrix (where N is sequence length), resulting in O(N^2) computational time and O(N^2) memory complexity. For long contexts, materializing the N x N attention matrix in GPU High Bandwidth Memory (HBM) creates severe memory bandwidth bottlenecks. FlashAttention is an exact, I/O-aware attention algorithm that optimizes GPU memory hierarchy. Instead of materializing intermediate N x N attention matrices in slow HBM, FlashAttention tiles the Q, K, and V matrices into smaller blocks loaded into fast on-chip SRAM, computing softmax scaling incrementally via online softmax and fusing the backward pass, reducing memory complexity from O(N^2) to O(N) and accelerating execution."),

        (48, "What is WordPiece / Byte-Pair Encoding (BPE) tokenization and why did it replace character and word tokenization?", "Medium",
         ["tokenization", "BPE", "WordPiece", "out-of-vocabulary", "subword", "vocabulary size", "NLP", "LLM"],
         "Explain limitations of word tokenization (massive vocabularies, OOV unknown tokens) and character tokenization (long sequences, weak semantics).",
         "Traditional tokenization faced a dilemma: Word-level tokenization produces massive vocabularies (hundreds of thousands of words), cannot handle unseen out-of-vocabulary (OOV) words, and ignores morphological prefixes/suffixes; Character-level tokenization eliminates OOV words but produces extremely long sequence lengths and strips semantic meaning from individual tokens. Byte-Pair Encoding (BPE) and WordPiece provide an optimal subword compromise: starting with a base character vocabulary, the algorithm iteratively merges the most frequently co-occurring byte or character pairs into single tokens up to a target vocabulary size (e.g., 32,000 to 100,000 tokens), handling common words as single tokens and decomposing rare words into subwords."),

        (49, "Explain the difference between Hard Margin and Soft Margin SVMs, and the role of hyperparameter C.", "Medium",
         ["SVM", "hard margin", "soft margin", "slack variable", "hyperparameter C", "regularization", "linear separation"],
         "Hard margin requires 100% linear separation with zero errors; Soft margin introduces slack variables xi with penalty C balancing margin width vs errors.",
         "Hard Margin SVM requires data to be strictly linearly separable with zero misclassifications, making it impossible on noisy data and prone to overfitting from outliers. Soft Margin SVM relaxes strict separation by introducing Slack Variables (xi_i >= 0), allowing data points to fall within the margin or even on the incorrect side of the decision boundary. The hyperparameter C controls the penalty trade-off: a small C prioritizes a wider margin, tolerating more misclassifications (higher bias, lower variance); a large C heavily penalizes slack violations, forcing the model to classify as many training points correctly as possible, resulting in a narrower margin (lower bias, higher variance)."),

        (50, "What is Quantization in deep learning and what are the trade-offs of Post-Training Quantization (PTQ) vs QAT?", "Hard",
         ["quantization", "PTQ", "QAT", "INT8", "FP16", "FP32", "inference latency", "memory compression", "accuracy loss"],
         "Explain mapping 32-bit floating point weights to 8-bit integers (4x memory reduction). Compare PTQ (fast, zero training) with QAT (fine-tuning with simulated quantization noise).",
         "Quantization reduces the precision of neural network weights and activations from 32-bit floating point (FP32) to lower-bit representations like 16-bit float (FP16), 8-bit integer (INT8), or 4-bit integer. This delivers 2x-4x memory compression and exploits integer matrix hardware (like Tensor Cores) for faster inference. 1) Post-Training Quantization (PTQ) quantizes a fully trained model using a calibration dataset to determine scale and zero-point parameters without retraining. It is fast and requires minimal compute, but can cause noticeable accuracy degradation on sensitive models; 2) Quantization-Aware Training (QAT) models quantization noise during training using fake-quantization nodes in the forward pass, allowing weights to adapt and minimizing accuracy drop."),

        (51, "Explain the differences between LLaMA, Mistral, and Claude model architectures and design choices.", "Medium",
         ["LLaMA", "Mistral", "RoPE", "SwiGLU", "RMSNorm", "sliding window attention", "GQA", "Transformer"],
         "Discuss modern Transformer enhancements: Rotary Position Embeddings (RoPE), SwiGLU activations, RMSNorm, and Grouped-Query Attention (GQA).",
         "Modern open-weight LLMs (like LLaMA and Mistral) introduce several foundational architectural enhancements over vanilla Transformers: 1) Rotary Position Embeddings (RoPE): Encodes positional information by rotating query and key representations in complex space, providing relative position awareness and context window extrapolation; 2) RMSNorm: Replaces standard LayerNorm by normalizing inputs using root mean square without mean-centering, reducing compute latency by ~10-50%; 3) SwiGLU Activation: Replaces standard ReLU/GELU with a Swish-Gated Linear Unit for richer non-linear expressiveness; 4) Grouped-Query Attention (GQA): Shares key and value heads across multiple query heads, drastically reducing KV-cache VRAM consumption during inference."),

        (52, "What is KV-Cache in Large Language Model inference and why does it exhaust GPU VRAM?", "Hard",
         ["KV-cache", "LLM inference", "autoregressive", "GPU VRAM", "attention", "memory bandwidth", "PagedAttention"],
         "During autoregressive generation, keys and values for preceding tokens are cached in VRAM to prevent O(N^2) recomputation, scaling with context length and batch size.",
         "In autoregressive generation, generating each new token requires attending to all preceding tokens in the prompt and generated sequence. Rather than recomputing Key (K) and Value (V) projections for historical tokens at every single generation step, the engine caches these tensors in GPU VRAM (the KV-Cache). However, the KV-cache grows linearly with sequence length, batch size, number of layers, and hidden dimensions (e.g., a 70B model with 16k context can consume several gigabytes of VRAM per concurrent request). This creates severe memory fragmentation and OOM risks, which systems like vLLM resolve using PagedAttention (virtual memory paging for KV-tensors)."),

        (53, "How does the Kolmogorov-Smirnov (KS) test detect distribution drift in production features?", "Medium",
         ["KS test", "Kolmogorov-Smirnov", "distribution drift", "data drift", "cumulative distribution function", "non-parametric"],
         "Explain comparing the Empirical Cumulative Distribution Functions (ECDFs) of baseline and production data, taking the maximum vertical distance D.",
         "The two-sample Kolmogorov-Smirnov (KS) test is a non-parametric statistical hypothesis test used to determine whether two continuous empirical data samples are drawn from the same underlying probability distribution. The algorithm constructs the Empirical Cumulative Distribution Function (ECDF) for the baseline training dataset F_1(x) and the production dataset F_2(x). It computes the test statistic D = sup_x |F_1(x) - F_2(x)|, which is the maximum absolute vertical distance between the two cumulative curves. If the p-value associated with D is smaller than the significance threshold (e.g., 0.05), we reject the null hypothesis, confirming statistically significant Data Drift that warrants model retraining."),

        (54, "What is Population Stability Index (PSI) and how do you interpret its thresholds?", "Easy",
         ["PSI", "population stability index", "data drift", "feature monitoring", "bins", "risk modeling"],
         "State the bins formula: sum((Actual% - Expected%) * ln(Actual% / Expected%)). Thresholds: <0.1 stable, 0.1-0.2 moderate drift, >0.2 significant drift.",
         "Population Stability Index (PSI) is a widely used quantitative metric in credit risk modeling and MLOps to measure how much a variable's distribution has shifted between a reference baseline population (Expected) and a current monitoring population (Actual). Features are partitioned into equal-frequency bins (typically 10-20 deciles). PSI is calculated as the sum across all bins of: (Actual% - Expected%) * ln(Actual% / Expected%). Interpretation thresholds: PSI < 0.1 indicates minimal to no distribution shift; 0.1 <= PSI <= 0.2 indicates moderate change that warrants closer observation; PSI > 0.2 indicates significant population drift requiring feature re-engineering or model retraining."),

        (55, "Explain the trade-offs of synthetic data generation using GANs vs Diffusion Models.", "Hard",
         ["synthetic data", "GAN", "diffusion model", "mode collapse", "score matching", "image generation", "data privacy"],
         "Contrast GAN adversarial min-max training (fast inference, prone to mode collapse) with Diffusion iterative denoising (stable training, high diversity, slow sampling).",
         "Generative Adversarial Networks (GANs) pit a Generator against a Discriminator in a minimax game: the generator synthesizes data from noise, and the discriminator classifies real vs fake. GANs have ultra-fast, single-step inference, but suffer from training instability and Mode Collapse (producing only a narrow subset of realistic samples). Diffusion Models reverse a gradual Gaussian noise degradation process via iterative score-matching denoising steps. Diffusion training is mathematically stable, provides comprehensive coverage of the data distribution, and avoids mode collapse, but requires multi-step sampling that makes inference computationally expensive unless accelerated by consistency models or latent distillation."),

        (56, "How do you evaluate generative LLM outputs when ground truth answers do not exist?", "Medium",
         ["LLM evaluation", "LLM-as-a-judge", "G-Eval", "perplexity", "human evaluation", "BLEU", "ROUGE", "rubrics"],
         "Discuss automated rubrics (LLM-as-a-Judge with pairwise ranking and chain-of-thought), task-specific guardrails (faithfulness, toxicity), and human evaluation.",
         "Evaluating generative outputs without ground truth labels requires combining automated, reference-free, and human-in-the-loop metrics: 1) LLM-as-a-Judge (e.g., G-Eval): Powerful judge models (like GPT-4) evaluate generated text against structured multi-criteria rubrics (relevance, coherence, faithfulness, conciseness) using Chain-of-Thought scoring and pairwise comparison to eliminate absolute score bias; 2) RAG Triad Metrics: Evaluating Context Relevance, Groundedness / Faithfulness (detecting hallucinations), and Answer Relevance; 3) Deterministic Guardrails: Checking programmatic constraints (JSON validity, regex conformity, toxicity thresholds); and 4) Stratified Human Evaluation with inter-annotator agreement (Cohen's Kappa)."),

        (57, "What is the difference between Word2Vec Skip-Gram and Continuous Bag of Words (CBOW)?", "Medium",
         ["Word2Vec", "skip-gram", "CBOW", "word embeddings", "negative sampling", "context window", "NLP"],
         "CBOW predicts the target center word from surrounding context words; Skip-gram predicts surrounding context words given the target center word.",
         "Word2Vec learns dense, low-dimensional vector representations of words where semantically similar words occupy proximate coordinates. 1) Continuous Bag of Words (CBOW): The model takes the average or sum of context words within a sliding window to predict the target center word. CBOW is computationally faster to train and produces slightly better representations for frequent words, but averages out context nuances; 2) Skip-Gram: Given a single target center word, the model predicts the probability distribution of context words surrounding it. Skip-gram performs exceptionally well with smaller training datasets and captures rare words and nuanced relationships far more effectively, often trained using Negative Sampling to avoid computing full softmax over the entire vocabulary."),

        (58, "How does the PageRank algorithm compute node importance in directed graphs?", "Medium",
         ["PageRank", "graph analytics", "random walk", "damping factor", "transition matrix", "power iteration", "Markov chain"],
         "Explain link analysis: a page's importance is derived from the number and quality of pages linking to it, modeling a random web surfer with damping factor d=0.85.",
         "PageRank assigns a numerical weight to each node in a directed graph to measure its relative importance, operating on the principle that important pages receive links from other important pages. It models a 'random surfer' who navigates web pages by clicking links with probability d (the Damping Factor, typically 0.85) or jumps to a completely random page with probability 1 - d (preventing the surfer from getting trapped in dead-end absorbing nodes). Mathematically, PageRank represents the stationary probability distribution of an ergodic Markov Chain, solved iteratively using the Power Iteration method over the graph's transition probability matrix until convergence."),

        (59, "What is the difference between Stratified Sampling and Cluster Sampling?", "Easy",
         ["stratified sampling", "cluster sampling", "sampling methodology", "heterogeneous", "homogeneous", "variance"],
         "Stratified: sample FROM every subgroup (subgroups are homogeneous internally). Cluster: sample ENTIRE selected subgroups (subgroups are heterogeneous internally).",
         "Both are probability sampling techniques: 1) Stratified Sampling divides the population into mutually exclusive, homogeneous subgroups (strata) based on an important characteristic (such as age, gender, or income brackets). Random samples are then drawn proportionally from EVERY stratum. This guarantees representation across all minority segments and minimizes sampling variance. 2) Cluster Sampling divides the population into naturally occurring, heterogeneous groups (clusters, like geographic school districts or cities). A random sample of CLUSTERS is selected, and all individuals within the chosen clusters are surveyed. Cluster sampling is cost-effective for geographically dispersed populations, but introduces higher sampling error."),

        (60, "How do you evaluate classification models when True Positives and False Positives have asymmetric business costs?", "Medium",
         ["cost-sensitive learning", "expected value", "cost matrix", "threshold tuning", "utility function", "business impact"],
         "Define a cost-benefit matrix: Expected Value = P(TP)*Benefit(TP) - P(FP)*Cost(FP) - P(FN)*Cost(FN) + P(TN)*Benefit(TN).",
         "Standard ML metrics (accuracy, F1) treat all classification errors equally, which fails in commercial applications where costs are highly asymmetric. For instance, in fraud detection, a False Negative (missing a $10,000 fraudulent wire) is 1000x worse than a False Positive (sending an automated verification SMS costing $0.05). To align models with business objectives: 1) Define a Cost-Benefit Matrix assigning explicit monetary values to TP, FP, TN, and FN; 2) Calculate Expected Value per transaction across different classification probability thresholds; 3) Perform Threshold Tuning to select the optimal operating cutoff that maximizes net monetary profit rather than arbitrary F1 balance; and 4) Incorporate Cost-Sensitive Loss Functions (e.g. weighted cross-entropy) during model training."),

        (61, "What is Causal Inference and how does it differ from Machine Learning Predictive Modeling?", "Hard",
         ["causal inference", "correlation vs causation", "counterfactual", "Do-calculus", "propensity score matching", "instrumental variables", "DAG"],
         "Predictive modeling learns P(Y|X) - correlation. Causal inference estimates P(Y | do(X)) - what happens to Y if we actively intervene on X (counterfactuals).",
         "Predictive machine learning models exploit statistical associations to predict an outcome: P(Y | X = x). However, correlation does not imply causation: a machine learning model might identify that users who carry lighters have higher rates of lung cancer, but banning lighters will not reduce cancer rates because smoking is the common confounding cause. Causal Inference estimates the causal effect of an intervention using Judea Pearl's 'do-calculus' or the potential outcomes framework: P(Y | do(X = x)). It addresses counterfactual questions ('What would this patient's outcome have been had they received the drug?'). When randomized controlled trials (A/B tests) are impossible, causal methods like Propensity Score Matching, Instrumental Variables, and Difference-in-Differences control for confounders."),

        (62, "Explain Difference-in-Differences (DiD) estimation for quasi-experimental policy evaluations.", "Medium",
         ["difference-in-differences", "DiD", "quasi-experiment", "parallel trends", "causal effect", "control group", "econometrics"],
         "Explain comparing the before-and-after change in a treatment group against the before-and-after change in an untreated control group.",
         "Difference-in-Differences (DiD) is a quasi-experimental statistical technique used to estimate causal effects when randomized A/B tests are unethical or infeasible (e.g., evaluating a new state tax policy or launching a nationwide marketing campaign). It compares the changes in outcomes over time between a Treatment Group (exposed to the intervention) and a Control Group (unexposed). The first difference calculates before-vs-after change within each group, and the second difference subtracts the control group's change from the treatment group's change, removing constant time-invariant group biases and macroeconomic temporal trends. The foundational identifying assumption is the Parallel Trends Assumption: in the absence of treatment, both groups would have followed parallel trajectory paths."),

        (63, "What is Propensity Score Matching (PSM) and how does it reduce selection bias in observational data?", "Hard",
         ["propensity score matching", "PSM", "selection bias", "observational study", "logistic regression", "nearest neighbor", "confounding"],
         "Estimate the probability of receiving treatment given baseline confounders e(X) = P(T=1|X), then match treated units to similar untreated units.",
         "In observational data, subjects choose whether to receive a treatment (e.g., users choosing to subscribe to a loyalty program), creating severe Selection Bias because treated individuals differ systematically from untreated individuals across confounding covariates (age, wealth, activity). Propensity Score Matching (PSM) balances the groups: 1) A logistic regression or gradient-boosted model estimates the Propensity Score e(X) = P(Treatment = 1 | Covariates X); 2) Each treated unit is matched to one or more untreated control units with nearly identical propensity scores (using nearest neighbor or caliper matching); 3) The causal treatment effect is evaluated exclusively across the balanced, matched pairs, simulating a randomized trial."),

        (64, "How does the Multi-Armed Bandit (MAB) algorithm balance Exploration vs Exploitation in production?", "Medium",
         ["multi-armed bandit", "exploration exploitation", "epsilon-greedy", "thompson sampling", "UCB", "regret minimization"],
         "Contrast fixed-allocation A/B testing with dynamic allocation: dynamically steering traffic to winning arms while exploring uncertain arms.",
         "Traditional A/B testing allocates traffic evenly (50/50) until statistical significance is reached, incurring high Opportunity Cost / Regret by sending users to inferior variants during the trial. Multi-Armed Bandit (MAB) algorithms solve the Exploration vs Exploitation trade-off in real time: 1) Epsilon-Greedy explores random arms with probability epsilon and exploits the current best arm with probability 1 - epsilon; 2) Upper Confidence Bound (UCB) selects the arm with the highest upper confidence limit of estimated reward ('optimism in the face of uncertainty'); 3) Thompson Sampling uses Bayesian posteriors, sampling from beta distributions to allocate traffic proportionally to the probability that an arm is the true optimal choice, minimizing cumulative regret."),

        (65, "What is Feature Store architecture (e.g., Feast) and why is it needed in production ML?", "Medium",
         ["feature store", "Feast", "online store", "offline store", "point-in-time correctness", "training-serving skew", "MLOps"],
         "Explain dual storage: low-latency key-value store (Redis) for real-time inference, and columnar store (BigQuery/Snowflake) for historical training with point-in-time joins.",
         "In production machine learning, feature engineering logic is often duplicated between training (SQL/Spark batch scripts) and real-time inference (Python/Go microservices), causing Training-Serving Skew when features diverge. A Feature Store (like Feast or Hopsworks) centralizes feature definitions, transformations, and access. It maintains two storage engines: 1) Online Store (Redis, DynamoDB): Low-latency key-value lookup providing the latest feature values for real-time model inference in sub-10 milliseconds; 2) Offline Store (BigQuery, Snowflake, Parquet on S3): Scalable historical storage that performs point-in-time correct joins ('time-travel') to prevent data leakage when assembling historical training datasets."),

        (66, "How do you evaluate and mitigate Model Hallucinations in LLMs?", "Hard",
         ["hallucination", "LLM", "RAG", "grounding", "temperature", "fine-tuning", "factuality", "chain-of-thought"],
         "Discuss root causes (statistical next-token sampling without true world model) and mitigations (RAG grounding, low temperature, chain-of-thought, citation constraints).",
         "LLM hallucinations occur when a model generates convincing, syntactically fluent statements that are factually false, unfaithful to provided source material, or non-existent. Root causes include training on noisy web corpora, statistical next-token prediction without truth grounding, and parametric knowledge degradation. Mitigations include: 1) Retrieval-Augmented Generation (RAG) to force the model to base answers on retrieved source documents; 2) Setting sampling temperature to 0 or low values for deterministic outputs; 3) Prompt Engineering techniques requiring explicit step-by-step citations and encouraging the model to reply 'I do not have enough information' when facts are absent; 4) Self-Consistency and Chain-of-Thought reasoning; and 5) Secondary validator / judge models that cross-reference claims against source text."),

        (67, "What is the difference between Generative Adversarial Networks (GANs) and Variational Autoencoders (VAEs)?", "Hard",
         ["GAN", "VAE", "variational autoencoder", "latent space", "reparameterization trick", "KL divergence", "generative modeling"],
         "VAEs use probabilistic encoders/decoders with smooth regularized latent spaces (KL divergence); GANs use adversarial generator/discriminator games.",
         "Both are deep generative architectures: 1) Variational Autoencoders (VAEs) are probabilistic models that encode input data into a parameterized probability distribution (mean mu and variance sigma) in latent space, using the Reparameterization Trick to permit backpropagation. The loss function balances Reconstruction Loss against KL Divergence (which regularizes the latent space toward a standard Gaussian). VAEs provide continuous, smooth, interpretable latent representations, but generate somewhat blurry images; 2) GANs use an adversarial game between a Generator and Discriminator without explicit probability density modeling, producing sharper, photorealistic samples but suffering from mode collapse and training instability."),

        (68, "How does the Isolation Forest algorithm isolate anomalies without density or distance calculations?", "Medium",
         ["isolation forest", "anomaly detection", "outliers", "path length", "random trees", "unsupervised"],
         "Explain recursive random splitting: anomalies are few and attribute-different, so they require fewer random partition cuts to isolate (short tree path length).",
         "Most anomaly detection algorithms compute local density or pairwise distances, which scale poorly to high dimensions. Isolation Forest is an unsupervised tree ensemble based on the premise that anomalies are 'few and different.' The algorithm recursively partitions data points by randomly selecting a feature and randomly selecting a split value between its min and max. Because anomalous points have distinct feature values, they require far fewer random splits to isolate into leaf nodes compared to normal cluster points. The Anomaly Score is calculated as an inverse monotonic function of the average Path Length across an ensemble of isolation trees: points with short path lengths are flagged as anomalies."),

        (69, "Explain the differences between L1, L2, and Smooth L1 (Huber) Loss in regression.", "Easy",
         ["L1 loss", "L2 loss", "Huber loss", "MAE", "MSE", "outliers", "gradient", "robustness"],
         "L2 (MSE) heavily penalizes large errors (non-robust to outliers); L1 (MAE) has constant gradients (robust, but non-smooth at 0); Huber is quadratic for small errors and linear for large.",
         "1) L2 Loss (Mean Squared Error / MSE) squares residuals ((y - y_hat)^2). Its derivative is proportional to error magnitude, providing smooth convergence, but it heavily penalizes large errors, causing models to be pulled disproportionately toward extreme outliers; 2) L1 Loss (Mean Absolute Error / MAE) takes absolute error (|y - y_hat|). Its derivative is constant (+1 or -1), making it exceptionally robust against outliers, but its gradient is discontinuous at zero, causing optimization oscillations near convergence; 3) Huber Loss (Smooth L1) combines the best of both: it behaves quadratically (like L2) for small errors (|e| <= delta) and linearly (like L1) for large errors (|e| > delta), offering smooth convergence with outlier robustness."),

        (70, "What is the difference between One-Hot Encoding and Target Encoding for categorical variables?", "Medium",
         ["one-hot encoding", "target encoding", "categorical variables", "high cardinality", "data leakage", "smoothing", "overfitting"],
         "One-Hot creates binary dummy columns (exploding dimensionality for high cardinality); Target Encoding replaces categories with the mean target value (requires smoothing).",
         "Categorical variables must be converted into numerical tensors for machine learning: 1) One-Hot Encoding creates a new binary (0/1) indicator column for each distinct category. It works well for low-cardinality categories (e.g., day of week), but causes dimensionality explosion, sparse matrix overhead, and severe tree inefficiency for high-cardinality features (e.g., zip codes, user IDs); 2) Target Encoding (Mean Encoding) replaces each categorical value with the average target value for that category across the training set. While it maintains a single compact numerical column, it risks severe target leakage and overfitting on rare categories, requiring k-fold out-of-fold calculation and Bayesian smoothing (m-estimate smoothing)."),

        (71, "What is Model Distillation (Knowledge Distillation) and how does temperature soften probability distributions?", "Hard",
         ["knowledge distillation", "teacher student", "temperature scaling", "soft targets", "model compression", "inference latency"],
         "Explain transferring knowledge from a large 'Teacher' model to a compact 'Student' model by matching softmax logits scaled by temperature T.",
         "Knowledge Distillation compresses a large, computationally heavy model (Teacher, like an ensemble or large LLM) into a lightweight, fast model (Student) suitable for low-latency production serving. Rather than training the student strictly on hard one-hot labels, the student is trained to mimic the full probability distribution (the 'dark knowledge') produced by the teacher's softmax output. The logits are scaled by a Temperature hyperparameter T (p_i = exp(z_i / T) / sum(exp(z_j / T))): higher temperatures soften the distribution, exposing subtle structural relationships and relative class rankings learned by the teacher that hard labels discard."),

        (72, "Explain the Cross-Entropy Loss function and its connection to Kullback-Leibler (KL) Divergence.", "Medium",
         ["cross-entropy", "KL divergence", "loss function", "information theory", "entropy", "log loss", "classification"],
         "Show formula H(p, q) = H(p) + D_KL(p || q). Because true label entropy H(p) is fixed, minimizing cross-entropy is equivalent to minimizing KL divergence.",
         "Cross-Entropy measures the difference between two probability distributions: the true distribution p (e.g., one-hot target vectors) and the predicted distribution q (e.g., softmax outputs). In information theory, Cross-Entropy H(p, q) = - sum(p(x) * log(q(x))) represents the average number of bits required to encode data from distribution p using a coding scheme optimized for distribution q. Mathematically, H(p, q) = H(p) + D_KL(p || q), where H(p) is the Shannon entropy of the true labels (which is constant) and D_KL is the Kullback-Leibler Divergence (relative entropy). Therefore, minimizing Cross-Entropy during classification training is mathematically equivalent to minimizing the KL divergence between predictions and true labels."),

        (73, "What is the difference between Covariate Shift and Prior Probability Shift?", "Medium",
         ["covariate shift", "prior probability shift", "dataset shift", "class balance", "data drift", "domain adaptation"],
         "Covariate Shift: input distribution P(X) changes while P(Y|X) remains constant. Prior Probability Shift: target distribution P(Y) changes while P(X|Y) remains constant.",
         "Dataset shift occurs when the joint distribution P(X, Y) differs between training and serving. Two primary forms exist: 1) Covariate Shift: The input feature distribution P(X) changes while the conditional target mapping P(Y|X) remains unchanged. For example, testing an autonomous driving model trained on daytime video in night conditions; 2) Prior Probability Shift (Label Shift): The distribution of the target variable P(Y) changes while the conditional feature distribution given the class P(X|Y) remains identical. For example, during a flu epidemic, the overall baseline probability of having the flu P(Y) surges, but the symptoms displayed by a flu patient P(X|Y) remain unchanged."),

        (74, "How do you evaluate and mitigate Gender or Racial Bias in Machine Learning models?", "Hard",
         ["fairness", "model bias", "disparate impact", "equalized odds", "demographic parity", "ethical AI", "counterfactual fairness"],
         "Discuss mathematical definitions of fairness (Demographic Parity, Equal Opportunity, Equalized Odds) and pre-/in-/post-processing mitigations.",
         "Algorithmic bias occurs when models systematically produce prejudicial or unfair outcomes against protected demographic cohorts. Practitioners evaluate fairness using formal statistical metrics: 1) Demographic Parity (Statistical Parity): Acceptance rates are equal across protected and unprotected groups (P(Y_hat=1 | A=0) = P(Y_hat=1 | A=1)); 2) Equal Opportunity: True Positive Rates are identical across groups; 3) Equalized Odds: Both TPR and FPR are identical across groups. Mitigations include: Pre-processing (re-weighting or adversarial debiasing of training data), In-processing (adding fairness constraint penalties to loss functions), and Post-processing (adjusting decision thresholds per demographic group to ensure equal opportunity)."),

        (75, "What is the Self-Consistency prompting technique in Large Language Models?", "Easy",
         ["self-consistency", "prompt engineering", "chain of thought", "majority voting", "reasoning", "LLM accuracy"],
         "Sample multiple reasoning paths with temperature > 0 and take the majority vote across the final answers.",
         "Standard Chain-of-Thought (CoT) prompting generates a single deterministic reasoning path (greedy decoding), which can stumble into an early arithmetic or logical error and cascade to an incorrect conclusion. Self-Consistency (introduced by Wang et al.) replaces greedy decoding by generating a diverse cohort of multiple reasoning paths (e.g., 10 to 40 samples) from the model using non-zero temperature sampling. The final answers extracted from all reasoning paths are aggregated, and the majority vote (mode) is selected as the final output. This significantly boosts accuracy on complex arithmetic, commonsense, and multi-step symbolic reasoning tasks."),

        (76, "Explain the architecture and training objective of Diffusion Models (DDPM).", "Hard",
         ["diffusion models", "DDPM", "forward process", "reverse process", "Markov chain", "score matching", "noise prediction"],
         "Forward process adds Gaussian noise in a Markov chain; Reverse process trains a U-Net to predict and subtract the added noise at each step.",
         "Denoising Diffusion Probabilistic Models (DDPM) generate data by inverting a destruction process: 1) Forward Process (Noising): A fixed Markov chain gradually adds small increments of Gaussian noise to an image over T timesteps according to a variance schedule, transforming structured data into pure isotropic Gaussian noise; 2) Reverse Process (Denoising): A neural network (typically a U-Net with attention) is trained to estimate the noise epsilon_theta added at any arbitrary timestep t given noisy input x_t. The objective loss is simplified L2 loss between the true added noise and predicted noise. Generation starts with pure noise, iteratively subtracting predicted noise over T steps to synthesize novel, high-fidelity images."),

        (77, "What is the difference between Zero-Shot, Few-Shot, and In-Context Learning in LLMs?", "Easy",
         ["zero-shot", "few-shot", "in-context learning", "prompting", "demonstrations", "LLM"],
         "Zero-shot provides only task instructions; Few-shot provides a few input-output demonstration exemplars within the context window; both require zero weight updates.",
         "These paradigms describe how foundation models perform tasks without gradient updates: 1) Zero-Shot: The model is given a natural language instruction and input data without any examples (e.g., 'Classify the sentiment of this text: [text] ->'); the model relies entirely on pre-trained parametric knowledge; 2) Few-Shot / In-Context Learning: The prompt includes a small number (typically 2 to 5) of illustrative input-output demonstration pairs followed by the target query. The model infers the input-output mapping pattern dynamically through self-attention across context activations without modifying any underlying model weights."),

        (78, "Explain how the U-Net architecture uses skip connections for image segmentation.", "Medium",
         ["U-Net", "image segmentation", "skip connections", "encoder decoder", "spatial resolution", "biomedical"],
         "Contracting path captures context; expanding path enables precise localization; skip connections copy high-resolution spatial features across paths.",
         "U-Net is a convolutional network designed for semantic segmentation. Its architecture forms a 'U' shape consisting of two paths: 1) Contracting Path (Encoder): Repeated blocks of convolutions and max pooling that progressively downsample spatial dimensions while expanding feature channel depth to extract high-level semantic context; 2) Expanding Path (Decoder): Transposed convolutions or upsampling that recover high-resolution spatial dimensions. Crucially, U-Net introduces Skip Connections that copy high-resolution feature maps directly from the contracting path to the corresponding expanding path, concatenating fine spatial details with high-level semantic context to achieve pixel-perfect boundary localization."),

        (79, "What is the difference between Mean Absolute Error (MAE) and Root Mean Squared Error (RMSE)?", "Easy",
         ["MAE", "RMSE", "loss function", "regression metrics", "outliers", "interpretability", "squared error"],
         "MAE is the average absolute error (linear penalty, robust to outliers); RMSE takes the square root of mean squared error (penalizes large errors heavily).",
         "Both are standard metrics for continuous regression evaluation: 1) Mean Absolute Error (MAE) = (1/n) * sum(|y - y_hat|): It measures the average magnitude of errors on a strictly linear scale, making it highly interpretable in the same units as the target variable and robust against extreme outliers; 2) Root Mean Squared Error (RMSE) = sqrt((1/n) * sum((y - y_hat)^2)): Because errors are squared before averaging, RMSE penalizes large errors much more severely than small ones. RMSE is preferred when large errors are especially catastrophic commercially (e.g., supply chain demand underestimation causing total stockouts)."),

        (80, "How do you detect and fix Target Leakage in real-world ML datasets?", "Medium",
         ["target leakage", "feature engineering", "temporal split", "correlation", "data hygiene", "pipeline"],
         "Identify features that are updated as a consequence of the target event occurring, or that include future information not available at inference time.",
         "Target leakage occurs when an independent variable includes information that directly or indirectly reflects the target outcome, which would be unavailable at the exact moment of real-time prediction. For example, using 'account_closure_ticket_created' to predict customer churn, or using patient post-operative antibiotic prescriptions to predict whether surgery will occur. Detection methods include: checking for unrealistically high feature correlations or feature importances (e.g., a single feature yielding 0.99 ROC-AUC), conducting rigorous timeline auditing of when each data point is logged in production databases, and enforcing strict chronological train/test splits."),

        (81, "What is the difference between Supervised Learning, Semi-Supervised Learning, and Self-Supervised Learning?", "Medium",
         ["supervised", "semi-supervised", "self-supervised", "pseudo-labeling", "contrastive learning", "unlabeled data"],
         "Supervised: human-labeled data. Semi-supervised: small labeled + large unlabeled dataset. Self-supervised: labels generated automatically from raw data (BERT, SimCLR).",
         "1) Supervised Learning trains on explicitly human-curated input-output pairs (X, Y) to learn a mapping function; 2) Semi-Supervised Learning leverages a small volume of labeled data alongside a vast volume of unlabeled data, utilizing techniques like pseudo-labeling (generating confident predictions on unlabeled data to re-train) or consistency regularization to build better decision boundaries at lower annotation cost; 3) Self-Supervised Learning trains on raw, unannotated data by automatically formulating supervisory pretext tasks directly from the data itself—such as predicting masked tokens (BERT), predicting the next word (GPT), or contrastive learning on augmented images (SimCLR)."),

        (82, "Explain how Multi-Task Learning improves generalization across related tasks.", "Medium",
         ["multi-task learning", "hard parameter sharing", "soft parameter sharing", "regularization", "transfer learning", "inductive bias"],
         "Shared lower layers learn universal representations; task-specific heads branch out. Acting as an inductive bias and implicit regularizer.",
         "Multi-Task Learning (MTL) trains a single machine learning model to solve multiple distinct but related tasks simultaneously (e.g., predicting sentiment, topic classification, and language dialect in a single NLP model). In Hard Parameter Sharing, lower convolutional or Transformer layers are shared across all tasks to learn universal, generalized feature representations, while top layers branch into task-specific heads. MTL improves generalization because the shared representation must satisfy multiple distinct objective loss functions simultaneously, acting as an implicit regularizer that prevents the model from overfitting to the statistical noise of any single task."),

        (83, "What is the difference between Precision-Recall curves and Receiver Operating Characteristic (ROC) curves?", "Easy",
         ["precision-recall", "ROC", "class imbalance", "true negative", "false positive rate", "threshold"],
         "ROC graphs TPR vs FPR; PR graphs Precision vs Recall. When negatives dominate, ROC remains insensitive while PR reveals sharp performance degradation.",
         "Both curves evaluate binary classification performance across varying decision thresholds. The ROC curve plots True Positive Rate (Recall) vs False Positive Rate (FPR), providing an assessment of how well the model separates the two classes across all thresholds. However, because FPR = FP / (FP + TN), an overwhelming number of negative examples (TN) keeps FPR low even with many false positives. The Precision-Recall (PR) curve plots Precision vs Recall; because precision explicitly incorporates False Positives in its denominator (TP / (TP + FP)) and ignores True Negatives, PR curves expose performance drops on rare positive classes that ROC masks."),

        (84, "How do you evaluate clustering performance when ground truth labels are NOT available?", "Medium",
         ["clustering evaluation", "silhouette score", "calinski-harabasz", "davies-bouldin", "unsupervised evaluation", "cluster cohesion"],
         "Discuss internal validation metrics: Silhouette Coefficient, Calinski-Harabasz Index (Variance Ratio), and Davies-Bouldin Index.",
         "When ground truth labels do not exist, clustering must be evaluated using internal validation metrics measuring cluster cohesion (compactness within clusters) and separation (distance between distinct clusters): 1) Silhouette Coefficient: Measures how similar an object is to its own cluster compared to neighboring clusters (ranging from -1 to +1, higher is better); 2) Calinski-Harabasz Index (Variance Ratio Criterion): Ratio of the sum of between-cluster dispersion to within-cluster dispersion (higher indicates dense, well-separated clusters); 3) Davies-Bouldin Index: Average similarity ratio of each cluster with its most similar cluster (lower is better, indicating better separation)."),

        (85, "Explain the difference between Covariance and Correlation.", "Easy",
         ["covariance", "correlation", "pearson", "standardization", "scale invariance", "linear relationship"],
         "Covariance measures directional linear relationship (scale-dependent, unbounded); Correlation normalizes covariance by standard deviations (scale-independent, -1 to +1).",
         "Both metrics quantify the degree to which two random variables move together. Covariance evaluates the joint variability of two variables: Cov(X, Y) = E[(X - E[X])(Y - E[Y])]. If positive, variables increase together; if negative, they move inversely. However, covariance is scale-dependent and unbounded (measured in units of X times units of Y), making it impossible to compare relationships across different features. Pearson Correlation normalizes covariance by the product of both variables' standard deviations: r = Cov(X, Y) / (sigma_X * sigma_Y). Correlation is dimensionless, scale-invariant, and bounded strictly between -1 (perfect negative linear correlation) and +1 (perfect positive linear correlation)."),

        (86, "What is the difference between Bagging and Stacking in ensemble learning?", "Medium",
         ["bagging", "stacking", "meta-learner", "ensemble", "blending", "cross-validation", "diversity"],
         "Bagging averages homogenous models trained on bootstrapped data; Stacking combines heterogeneous models using a higher-level meta-learner.",
         "Bagging (Bootstrap Aggregating) trains multiple instances of the same base algorithm (homogeneous models, typically decision trees) in parallel on randomly resampled subsets of the training data with replacement, combining their outputs via majority voting or simple averaging to reduce variance. Stacking (Stacked Generalization) trains multiple diverse, heterogeneous algorithms (e.g., XGBoost, Logistic Regression, Random Forest, and a Neural Network) on the full dataset. The predictions of these base models are then fed as input features into a secondary Meta-Learner (typically a regularized logistic/linear model) that learns how to optimally weight and combine their predictions."),

        (87, "How does the Attention mechanism solve the bottleneck problem in Seq2Seq models?", "Medium",
         ["attention", "seq2seq", "encoder-decoder", "context vector", "information bottleneck", "RNN", "machine translation"],
         "Traditional Seq2Seq compresses the entire input sequence into a single fixed-size context vector; Attention allows decoders to dynamically look back at all encoder hidden states.",
         "Traditional Recurrent Neural Network (RNN) Encoder-Decoder architectures compress an input sequence of arbitrary length into a single fixed-length hidden vector (the context vector) before feeding it to the decoder. For long sentences, this fixed vector becomes an acute Information Bottleneck, causing the model to forget early tokens. The Bahdanau/Luong Attention mechanism eliminates this bottleneck: instead of forcing the encoder to compress everything into one vector, the decoder is granted dynamic, direct access to all intermediate encoder hidden states. At each decoding step, the model computes attention weights over all input tokens, generating a dynamically tailored context vector."),

        (88, "What are the common strategies for hyperparameter optimization: Grid Search, Random Search, and Bayesian Optimization?", "Medium",
         ["hyperparameter tuning", "grid search", "random search", "bayesian optimization", "Optuna", "Gaussian process", "exploration"],
         "Grid Search exhaustively evaluates all combinations; Random Search samples uniformly (more efficient in high dimensions); Bayesian Optimization models prior evaluations to pick promising configurations.",
         "1) Grid Search performs an exhaustive brute-force search over a manually specified Cartesian product of hyperparameter values. It guarantees full coverage of the grid, but suffers from exponential computational complexity as hyperparameters increase; 2) Random Search samples hyperparameter combinations uniformly at random from specified distributions. Bergstra and Bengio proved that Random Search is significantly more efficient than Grid Search because most ML models are sensitive to only a small subset of hyperparameters; 3) Bayesian Optimization (e.g., Optuna, Tree-structured Parzen Estimators / TPE) models the objective function as a probabilistic surrogate (like a Gaussian Process), using past evaluation results to intelligently balance exploration of uncertain spaces with exploitation of promising hyperparameter regions."),

        (89, "Explain the differences between L1, L2, and ElasticNet regularization penalties in regression models.", "Easy",
         ["elasticnet", "L1", "L2", "regularization", "multicollinearity", "sparsity", "glmnet"],
         "ElasticNet combines L1 (Lasso) and L2 (Ridge): Loss + r*alpha*|w| + 0.5*(1-r)*alpha*w^2, overcoming Lasso's arbitrary selection among correlated features.",
         "Regularization techniques add penalties to the loss function to constrain model complexity and prevent overfitting: 1) L1 Regularization (Lasso) penalizes the absolute sum of weights, producing sparse models by driving irrelevant feature weights to exactly zero, but behaves erratically when features are highly correlated (arbitrarily selecting one and zeroing the rest); 2) L2 Regularization (Ridge) penalizes the squared sum of weights, shrinking weights smoothly toward zero and handling multicollinearity, but retains all features; 3) ElasticNet linearly combines both penalties: alpha * (r * L1 + (1 - r) * L2). It encourages sparsity while grouping correlated variables together, outperforming Lasso when predictors exceed observations (p > n)."),

        (90, "What is the difference between Micro-Averaging, Macro-Averaging, and Weighted-Averaging for multi-class classification?", "Medium",
         ["micro-average", "macro-average", "weighted-average", "multi-class", "class imbalance", "F1-score"],
         "Macro: unweighted mean across classes (treats all classes equally). Weighted: weighted by support. Micro: aggregate global TP, FP, FN across all classes.",
         "When evaluating multi-class classification metrics (like F1-score): 1) Macro-Averaging calculates the metric independently for each individual class and takes their unweighted arithmetic mean. It treats all classes equally, making it ideal for highlighting poor performance on small, rare minority classes; 2) Weighted-Averaging calculates the metric for each class and weights the mean by the Support (number of true instances) of each class. It accounts for class imbalances but can mask poor performance on small classes; 3) Micro-Averaging pools all global True Positives, False Positives, and False Negatives across all classes to compute a single overall metric, heavily dominated by majority classes."),

        (91, "How does the Naive Bayes classifier work, and what is its 'naive' independence assumption?", "Easy",
         ["naive bayes", "bayes theorem", "conditional independence", "prior", "likelihood", "text classification"],
         "It assumes all input features are conditionally independent given the class label: P(x_1, x_2, ..., x_n | C) = product(P(x_i | C)).",
         "The Naive Bayes classifier is a probabilistic supervised learning algorithm rooted in Bayes' Theorem: P(Class | Features) = P(Features | Class) * P(Class) / P(Features). It is called 'naive' because it makes the strong, unrealistic assumption of Class-Conditional Independence: it assumes that the presence or value of any given feature is completely independent of every other feature, given the class label. This simplifies calculating the joint likelihood to the product of individual feature likelihoods: P(x_1, x_2, ..., x_n | C) = product(P(x_i | C)). Despite this unrealistic assumption, Naive Bayes performs surprisingly well in high-dimensional text classification (spam detection) and trains in O(nd) linear time."),

        (92, "What is Perplexity in language modeling and how does it relate to Cross-Entropy Loss?", "Medium",
         ["perplexity", "cross-entropy", "language modeling", "LLM evaluation", "exponentiation", "branching factor"],
         "Perplexity = exp(Cross-Entropy Loss). It represents the weighted branching factor: the effective number of words the model is choosing between.",
         "Perplexity (PPL) is the standard intrinsic evaluation metric for autoregressive language models, measuring how well a probability model predicts a sample of text. Formally, perplexity is defined as the exponentiated cross-entropy loss: PPL = exp(Cross-Entropy) = exp(- (1/N) * sum(log(P(w_i | w_<i)))). A lower perplexity score indicates that the model is less 'perplexed' or surprised by the text, assigning higher probabilities to the actual tokens. Intuitively, a perplexity of K means that at each token prediction step, the model is as uncertain as if it were choosing uniformly at random among K candidate words (the effective branching factor)."),

        (93, "How does Gradient Accumulation enable training large models with limited GPU VRAM?", "Easy",
         ["gradient accumulation", "effective batch size", "VRAM", "deep learning", "mini-batch", "optimizer step"],
         "Compute gradients over micro-batches, sum them without updating weights, and call optimizer.step() only after N steps.",
         "Training deep neural networks with large batch sizes improves gradient estimation stability and generalization, but large batches can exceed GPU VRAM and trigger Out-Of-Memory (OOM) errors. Gradient Accumulation overcomes this hardware limit: the desired large Effective Batch Size is divided into smaller Micro-Batches that fit in GPU memory. The model executes the forward pass and backpropagation on each micro-batch, calculating gradients and accumulating (summing) them in memory with `loss.backward()` without calling `optimizer.step()`. Once the target number of micro-batches have accumulated (e.g., 4 steps of batch size 16), the optimizer updates the weights once, simulating a full batch size of 64."),

        (94, "What is the difference between Generative Adversarial Networks (GANs) and Autoregressive models for image synthesis?", "Medium",
         ["GAN", "autoregressive image", "PixelCNN", "diffusion", "sampling speed", "likelihood", "image generation"],
         "GANs generate entire images in parallel in a single forward pass; Autoregressive image models (PixelCNN) predict pixel-by-pixel sequentially (very slow).",
         "1) Generative Adversarial Networks (GANs) synthesize images in a single parallel feedforward pass: a generator maps a latent noise vector to a complete image tensor, evaluated by an adversarial discriminator. GANs have lightning-fast inference and produce sharp visuals, but suffer from training instability and do not provide an explicit tractable likelihood function; 2) Autoregressive Image Models (like PixelRNN, PixelCNN, and VQ-VAE with Transformers) model image generation as a sequential joint probability distribution over pixels or discrete codebook tokens (P(x) = product(P(x_i | x_<i))). They provide exact log-likelihood optimization and stable training without mode collapse, but sampling an image requires sequential pixel-by-pixel generation, resulting in very slow inference."),

        (95, "How do you evaluate Multi-Label classification where samples can belong to multiple classes simultaneously?", "Medium",
         ["multi-label", "hamming loss", "subset accuracy", "binary cross entropy", "micro macro F1", "classification"],
         "Contrast multi-class (one mutually exclusive label) with multi-label (independent binary labels per class). Use Hamming Loss and Subset Accuracy.",
         "In Multi-Label classification, an observation can possess any number of non-exclusive labels simultaneously (e.g., an article tagged with both 'Economy' and 'Politics'). Unlike multi-class models that use Softmax and Categorical Cross-Entropy, multi-label models use independent Sigmoid activations on each output neuron and Binary Cross-Entropy loss per class. Evaluation metrics include: 1) Subset Accuracy (Exact Match Ratio): Proportion of samples where all predicted labels match the true label set exactly (very strict); 2) Hamming Loss: The fraction of incorrect labels relative to total labels; 3) Micro- and Macro-averaged F1 scores computed across all binary label dimensions."),

        (96, "What is the role of Positional Encodings in Transformer architectures?", "Easy",
         ["positional encoding", "Transformer", "permutation invariance", "self-attention", "sinusoidal", "RoPE"],
         "Because self-attention is permutation-invariant (order-agnostic), positional encodings inject word sequence order into input embeddings.",
         "The Self-Attention mechanism is inherently permutation-invariant: if you shuffle the tokens in an input sentence, the resulting attention weights and output vectors are identical except for row ordering, meaning a Transformer has zero natural awareness of word sequence order. Positional Encodings solve this by adding or concatenating positional information to token embeddings before the first Transformer block. Early Transformers used Sinusoidal Positional Encodings (fixed sine and cosine waves of different frequencies allowing the model to attend to relative positions); modern architectures use learnable embeddings, ALiBi, or Rotary Position Embeddings (RoPE) that apply complex rotational matrices directly to Query and Key tensors."),

        (97, "Explain the differences between Softmax, Sigmoid, and Argmax activation functions.", "Easy",
         ["softmax", "sigmoid", "argmax", "activation function", "probability", "multi-class", "binary"],
         "Sigmoid maps single real values to (0, 1) independently; Softmax normalizes a vector of logits to sum to 1.0; Argmax selects the single index with maximum value.",
         "1) Sigmoid: sigma(z) = 1 / (1 + e^-z). It maps any real-valued number into a range between 0 and 1. It is used for binary classification or multi-label output layers where each class probability is evaluated independently; 2) Softmax: Extends sigmoid to multi-class settings: sigma(z)_i = exp(z_i) / sum(exp(z_j)). It normalizes a vector of K real-valued logits into a categorical probability distribution where all values are positive and strictly sum to 1.0; 3) Argmax: A non-differentiable step function that selects the discrete index of the maximum value in a vector. It cannot be used during backpropagation, but is used at inference time to convert probabilities into final discrete class predictions."),

        (98, "How do you detect and handle Overfitting in deep learning models?", "Easy",
         ["overfitting", "regularization", "dropout", "early stopping", "data augmentation", "weight decay", "validation loss"],
         "Symptoms: Training loss decreases while validation loss diverges. Mitigations: Dropout, Early Stopping, Data Augmentation, L2 Weight Decay.",
         "Overfitting occurs when a high-capacity model memorizes the statistical noise and idiosyncrasies of the training data rather than learning generalizable underlying patterns, manifested when training loss continues decreasing while validation loss begins diverging upward. Mitigations include: 1) Early Stopping: Monitoring validation loss and halting training when performance plateaus; 2) Dropout: Randomly zeroing out a percentage of neuron activations during training to prevent co-adaptation; 3) Data Augmentation: Synthetically expanding training data (rotations, crops, jitter) to expose the model to diverse variations; 4) L2 Weight Decay: Penalizing large weights; and 5) Simplifying model capacity."),

        (99, "What is the difference between Feature Importance from Random Forest vs SHAP (SHapley Additive exPlanations)?", "Hard",
         ["SHAP", "feature importance", "game theory", "interpretability", "MDI", "permutation importance", "additive"],
         "MDI in Random Forests is biased toward high-cardinality features and lacks directionality; SHAP uses cooperative game theory to provide local, additive, direction-aware explanations.",
         "Traditional Random Forest Mean Decrease in Impurity (MDI / Gini Importance) calculates total purity gain per feature, but suffers from two flaws: it artificially favors high-cardinality numerical variables, and it provides only global importance without indicating whether a feature positively or negatively influenced an individual prediction. SHAP (SHapley Additive exPlanations) is rooted in cooperative game theory, calculating the marginal contribution of each feature value across all possible feature coalitions. SHAP guarantees consistency and local accuracy: individual feature SHAP values sum up to the exact difference between the model prediction and baseline expected value, providing direction-aware, instance-level interpretability."),

        (100, "How do you architect an end-to-end Machine Learning system for real-time Fraud Detection?", "Hard",
         ["fraud detection", "real-time ML", "feature store", "streaming", "low latency", "Kafka", "Redis", "imbalanced data"],
         "Walk through: Event ingestion (Kafka) -> Real-time feature calculation (Flink + Redis) -> Low-latency model scoring (<50ms) -> Asymmetric thresholding -> Asynchronous human review.",
         "A production real-time fraud detection engine must evaluate transactions within 50 milliseconds: 1) Ingestion: Incoming transaction events stream through Apache Kafka into a stateful streaming processor (Apache Flink); 2) Real-Time Feature Store: Flink computes sliding-window aggregations (e.g., 'number of transactions in last 10 minutes', 'distance from last swipe') and writes them to an ultra-low-latency in-memory feature store (Redis); 3) Inference Engine: A containerized scoring service (ONNX Runtime / Triton) fetches user features from Redis, combines them with transaction payload data, and runs inference using a light gradient-boosted ensemble (XGBoost/LightGBM); 4) Decisioning & Fallback: Cost-sensitive decision thresholds categorize outputs into Approve, Decline, or Step-Up Authentication (MFA); 5) Monitoring: Logs stream to a data lake for asynchronous human review and continuous model drift tracking.")
    ]

    all_questions = []
    for item in questions_raw + topics_26_to_100:
        num, text, diff, kws, tips, ans = item
        all_questions.append({
            "id": f"ds_{num}",
            "text": text,
            "difficulty": diff,
            "keywords": kws,
            "tips": tips,
            "model_answer": ans
        })
    return all_questions
